package br.org.ong.controller;
import br.org.ong.dto.request.VoluntarioRequest; import br.org.ong.dto.response.VoluntarioResponse; import br.org.ong.service.VoluntarioService; import jakarta.validation.Valid; import java.util.List; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/voluntarios") @PreAuthorize("hasRole('COMUM')") public class VoluntarioController {private final VoluntarioService service;public VoluntarioController(VoluntarioService service){this.service=service;}@PostMapping public VoluntarioResponse inscrever(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody VoluntarioRequest q){return VoluntarioResponse.from(service.inscrever(jwt.getSubject(),q.projetoId(),true,q.observacao()));}@GetMapping("/minhas") public List<VoluntarioResponse> minhas(@AuthenticationPrincipal Jwt jwt){return service.minhas(jwt.getSubject()).stream().map(VoluntarioResponse::from).toList();}@PutMapping("/{id}/encerrar") public VoluntarioResponse encerrar(@PathVariable String id,@AuthenticationPrincipal Jwt jwt){return VoluntarioResponse.from(service.encerrarMeu(id,jwt.getSubject()));}}
